<?php
function parallel012(string $mode,int $uid,int $content,int $answer=0): array {global $tmp;$jobs=[];for($i=0;$i<8;$i++){$process=proc_open([PHP_BINARY,'-d','ffi.enable=1',__DIR__.'/community_worker.php',$tmp.'/config.json',$mode,(string)$uid,(string)$content,(string)$answer],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$process,$pipes];}$out=[];foreach($jobs as [$process,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0){throw new RuntimeException($stderr);}$out[]=trim($stdout);}return $out;}
test('eight concurrent circle joins make one membership and one charge',static function()use($a){$uid=fresh012('circle_parallel012');$circle=circle012(['join_price'=>'90']);$before=funds($uid,'points');$out=parallel012('circle',$uid,$circle);same(1,count(array_filter($out,static function($v){return $v==='joined';})));same(7,count(array_filter($out,static function($v){return $v==='conflict';})));same($before-90,funds($uid,'points'));same(1,(int)$a->db->value("SELECT COUNT(*) FROM cy_orders WHERE user_id=? AND item_id=? AND kind='circle'",[$uid,$circle]));});
test('eight concurrent answer acceptances award held points exactly once',static function()use($a){$owner=fresh012('bounty_owner_parallel012');$winner=fresh012('bounty_winner_parallel012');$q=thread012($owner);$answer=answer012($q,$winner);$b=$a->bounties->fund(account($owner),$q,150,7,$a->content);$before=funds($winner,'points');$out=parallel012('award',$owner,$q,$answer);same(8,count(array_filter($out,static function($v){return $v==='accepted';})));same($before+150,funds($winner,'points'));same('awarded',$a->bounties->get($q)['status']);same(1,(int)$a->db->value("SELECT COUNT(*) FROM cy_audit WHERE action='bounty.awarded' AND target=?",[$q.':'.$winner]));});
test('post-concurrency asset ledger still reconciles',static function()use($a){foreach($a->db->all('SELECT * FROM cy_users') as $row){foreach(Chengyu\Services\Wallet::CURRENCIES as $currency){same((int)$row[$currency],(int)$a->db->value('SELECT COALESCE(SUM(delta),0) FROM cy_ledger WHERE user_id=? AND currency=?',[(int)$row['id'],$currency]));}}});
